import { Component, Signal } from "solid-js";

import { RadioButton } from "#core/ui-next/components/radio-button.jsx";
import { TextInput } from "#core/ui-next/sandbox/components-browser/components/text-input.jsx";

export interface BoundStringProps {
	name: string;
	signal: Signal<string | undefined>;
}

export const BoundString: Component<BoundStringProps> = (props) => {
	// eslint-disable-next-line solid/reactivity
	const [getter, setter] = props.signal;

	return (
		<div class="my-2 flex flex-col">
			<div class="text-center">{props.name}</div>
			<div class="relative h-10">
				<TextInput
					class="flex-grow w-full absolute"
					value={getter()}
					onInput={(e) => setter(e.currentTarget.value)}
				/>
			</div>
		</div>
	);
};

export interface BoundBooleanProps {
	name: string;
	signal: Signal<boolean | undefined>;
}

export const BoundBoolean: Component<BoundBooleanProps> = (props) => {
	// eslint-disable-next-line solid/reactivity
	const [getter, setter] = props.signal;

	return (
		<div class="my-2 flex flex-row items-center">
			<RadioButton
				class="mr-2"
				isChecked={getter()}
				onActivate={() => setter((v) => !v)}
			/>
			{props.name}
		</div>
	);
};

export interface BoundNumberProps {
	name: string;
	signal: Signal<number | undefined>;
}

export const BoundNumber: Component<BoundNumberProps> = (props) => {
	// eslint-disable-next-line solid/reactivity
	const [getter, setter] = props.signal;

	return (
		<div class="my-2 flex flex-col">
			<div class="text-center">{props.name}</div>
			<div class="relative h-10">
				<TextInput
					class="flex-grow w-full absolute"
					type="number"
					value={getter()?.toString() ?? 0}
					onInput={(e) => setter(Number(e.currentTarget.value) as number)}
				/>
			</div>
		</div>
	);
};
